24: async function api(caminho, corpo) {
25:   const op = corpo ? { method: "POST", headers: { "Content-Type": "application/json", "X-Cliente": "interface" }, body: JSON.stringify(corpo) } : {};
26:   const r = await fetch(caminho, op);
27:   const j = await r.json();
28:   if (!r.ok) throw new Error(j.erro || r.status);
29:   return j;
30: }

141: // ---------------- evidência ----------------
142: function travar(v) { ["#b-ajustar", "#b-comparar", "#b-amostrar"].forEach((s) => ($(s).disabled = v)); }
143: function sig(s) {
144:   if (!s) return "";
145:   return `<div class="card">significância local: z = <b>${s.z_local.toFixed(2)}</b> (p = ${s.p_local.toExponential(2)})<br>
146:     corrigida por <b>${s.n_familias}</b> família(s) de teste do livro: z = <b>${s.z_global.toFixed(2)}</b> (p = ${s.p_global.toExponential(2)})</div>`;
147: }
148: $("#b-ajustar").onclick = async () => {
149:   travar(true); $("#ev-texto").textContent = "ajustando…";
