154:       `χ² = ${a.chi2.toFixed(3)} com ${a.gl} g.l. · H₀ = ${a.theta.H0.toFixed(2)} ± ${(s.H0 || 0).toFixed(2)}\nα√e = ${r.beta_tgl.toFixed(6)} está a ${(r.beta_tgl_em_sigma_JtJ || 0).toFixed(2)} σ (JᵀJ)` + sig(r.significancia);
