186: function mostrarPosterior(r) {
187:   const b = r.resumo.beta, hb = r.hist_beta;
188:   const xs = hb.bordas.slice(0, -1).map((v, i) => (v + hb.bordas[i + 1]) / 2), w = hb.bordas[1] - hb.bordas[0], mx = Math.max(...hb.contagens);
189:   const barras = xs.map((x, i) => ({ x, y: hb.contagens[i] / mx, w: 0, cor: COR.azul }));
190:   grafico($("#g-post"), {
191:     series: [{ x: xs, y: hb.contagens.map((c) => c / mx), cor: COR.azul, larg: 2 }], ylim: [0, 1.08], xlim: [Math.min(hb.bordas[0], -0.001), Math.max(hb.bordas.at(-1), r.beta_tgl * 1.15)],
192:     vlinhas: [{ x: 0, cor: COR.cinza, dash: [4, 4], rot: "0" }, { x: r.beta_tgl, cor: COR.ouro, rot: "α√e" }, { x: b.median, cor: COR.azul, dash: [2, 3] }], xrot: "β",
193:   });
194:   const h2 = r.hist_beta_H0;
195:   mapa($("#g-2d"), h2.contagens, h2.bordas_beta, h2.bordas_H0, { vlinhas: [{ x: 0, cor: COR.cinza, dash: [4, 4] }, { x: r.beta_tgl, cor: COR.ouro }], xrot: "β", yrot: "H₀" });
196:   $("#ev-texto").innerHTML = `<span class="estatuto">${r.estatuto}</span>\n<span class="grande">β = ${b.median.toFixed(5)} (+${b.sigma_upper.toFixed(5)} / −${b.sigma_lower.toFixed(5)})</span>\n` +
197:     `H₀ = ${r.resumo.H0.median.toFixed(2)} · ${r.walkers} walkers × ${r.passos} passos em ${r.segundos} s · aceitação ${r.aceitacao_media.toFixed(2)} · amostras efetivas ≈ ${Math.round(r.amostras_efetivas)}\n` +
198:     `fração do posterior com β ≥ α√e: ${(100 * r.fracao_beta_acima_de_beta_tgl).toFixed(3)}% · com β ≥ 0: ${(100 * r.fracao_beta_acima_de_zero).toFixed(1)}%` + sig(r.significancia);

323: async function carregarLivro() {
