328:       l.ultimas.map((u) => `<tr><td>${u.ts}</td><td>${u.cliente}</td><td>${u.operacao}</td><td>${u.conjuntos.join(", ")}</td><td>${u.estatuto}</td><td>${u.p_local === null ? "—" : (+u.p_local).toExponential(2)}</td></tr>`).join("") + "</table>";
